import { z } from "zod";
import { seededRng, shuffle, type Rng } from "../core/seeded";
import { checkTimeline, type SoloGameDefinition, type SoloVerifyResult } from "../core/solo";

/**
 * Mahjong Garden: solitaire tile matching.
 *
 * Positions use half-tile units: a tile at (x, y, z) covers x..x+2, y..y+2 on
 * layer z. A tile is free when no tile on the layer above overlaps it and its
 * left or right side is open. Boards are generated by "reverse play": we
 * repeatedly remove two free positions from the full layout and give them a
 * matching pair, so the removal order is a guaranteed solution.
 */

export interface Slot {
  x: number;
  y: number;
  z: number;
}

/** Tile kinds: 0–8 dots, 9–17 bamboo, 18–26 characters, 27–30 winds, 31–33 dragons, 34–37 flowers, 38–41 seasons. */
export const FLOWERS = [34, 35, 36, 37];
export const SEASONS = [38, 39, 40, 41];
export const matchKey = (kind: number) => (kind >= 38 ? 38 : kind >= 34 ? 34 : kind);
export const tilesMatch = (a: number, b: number) => matchKey(a) === matchKey(b);

function grid(w: number, h: number, z: number, baseW: number, baseH: number): Slot[] {
  const out: Slot[] = [];
  const ox = baseW - w;
  const oy = baseH - h;
  for (let r = 0; r < h; r++) for (let c = 0; c < w; c++) out.push({ x: ox + c * 2, y: oy + r * 2, z });
  return out;
}

function layout(layers: [number, number][], wings: boolean): Slot[] {
  const [w0, h0] = layers[0]!;
  const slots = layers.flatMap(([w, h], z) => grid(w, h, z, w0, h0));
  if (wings) slots.push({ x: -2, y: h0 - 1, z: 0 }, { x: w0 * 2, y: h0 - 1, z: 0 });
  return slots;
}

export const LAYOUTS = {
  pebble: { name: "Pebble", difficulty: "Easy", slots: layout([[6, 4], [4, 2], [2, 2]], false), parSeconds: 150 },
  lotus: { name: "Lotus", difficulty: "Medium", slots: layout([[8, 5], [6, 3], [4, 2], [2, 2]], true), parSeconds: 330 },
  pagoda: { name: "Pagoda", difficulty: "Hard", slots: layout([[10, 6], [8, 4], [6, 2], [4, 2], [2, 2]], true), parSeconds: 600 },
} as const;
export type LayoutId = keyof typeof LAYOUTS;
export const LAYOUT_IDS = Object.keys(LAYOUTS) as LayoutId[];

export const mahjongConfigSchema = z.object({ layout: z.enum(["pebble", "lotus", "pagoda"]).default("pebble") });
export type MahjongConfig = z.infer<typeof mahjongConfigSchema>;

export const mahjongMoveSchema = z.discriminatedUnion("k", [
  z.object({ k: z.literal("match"), a: z.number().int().min(0).max(200), b: z.number().int().min(0).max(200), t: z.number().int() }),
  z.object({ k: z.literal("undo"), t: z.number().int() }),
  z.object({ k: z.literal("shuffle"), t: z.number().int() }),
  z.object({ k: z.literal("hint"), t: z.number().int() }),
]);
export type MahjongMove = z.infer<typeof mahjongMoveSchema>;
export const mahjongLogSchema = z.array(mahjongMoveSchema).max(2000);

export interface MahjongState {
  layout: LayoutId;
  slots: readonly Slot[];
  /** Tile kind per slot, or null once removed. */
  tiles: (number | null)[];
  score: number;
  matches: number;
  hints: number;
  shuffles: number;
  undos: number;
  lastMatchAt: number | null;
  combo: number;
  won: boolean;
}

export const SCORE = { match: 20, comboBonus: 10, hint: -30, shuffle: -50, undo: -10, clear: 500 };
const COMBO_WINDOW_MS = 4000;

// ---------------------------------------------------------------------------
// Geometry
// ---------------------------------------------------------------------------

const overlaps = (a: Slot, b: Slot) => Math.abs(a.x - b.x) < 2 && Math.abs(a.y - b.y) < 2;

export function isFree(slots: readonly Slot[], present: (i: number) => boolean, i: number): boolean {
  const s = slots[i]!;
  let left = false;
  let right = false;
  for (let j = 0; j < slots.length; j++) {
    if (j === i || !present(j)) continue;
    const o = slots[j]!;
    if (o.z === s.z + 1 && overlaps(o, s)) return false;
    if (o.z === s.z && Math.abs(o.y - s.y) < 2) {
      if (o.x === s.x - 2) left = true;
      if (o.x === s.x + 2) right = true;
    }
  }
  return !(left && right);
}

export const freeTiles = (s: MahjongState) =>
  s.tiles.flatMap((t, i) => (t !== null && isFree(s.slots, (j) => s.tiles[j] !== null, i) ? [i] : []));

/** All pairs of matching free tiles. */
export function availablePairs(s: MahjongState): [number, number][] {
  const free = freeTiles(s);
  const pairs: [number, number][] = [];
  for (let i = 0; i < free.length; i++)
    for (let j = i + 1; j < free.length; j++) if (tilesMatch(s.tiles[free[i]!]!, s.tiles[free[j]!]!)) pairs.push([free[i]!, free[j]!]);
  return pairs;
}

// ---------------------------------------------------------------------------
// Generation
// ---------------------------------------------------------------------------

/** The full 144-tile set as 72 matching pairs. */
function allPairs(): [number, number][] {
  const pairs: [number, number][] = [];
  for (let k = 0; k < 34; k++) pairs.push([k, k], [k, k]);
  pairs.push([34, 35], [36, 37], [38, 39], [40, 41]);
  return pairs;
}

/**
 * Assigns `pairs` to the slots in `positions` so the board can be cleared:
 * pick two simultaneously free positions, give them a pair, remove them, repeat.
 */
function placeSolvable(
  slots: readonly Slot[],
  positions: number[],
  pairs: [number, number][],
  rng: Rng,
): { placed: Map<number, number>; solution: [number, number][] } | null {
  for (let attempt = 0; attempt < 200; attempt++) {
    const remaining = new Set(positions);
    const placed = new Map<number, number>();
    const solution: [number, number][] = [];
    const queue = shuffle([...pairs], rng);
    let stuck = false;
    while (remaining.size) {
      const free = [...remaining].filter((i) => isFree(slots, (j) => remaining.has(j), i));
      if (free.length < 2) {
        stuck = true;
        break;
      }
      const a = free[rng.int(free.length)]!;
      const rest = free.filter((i) => i !== a);
      const b = rest[rng.int(rest.length)]!;
      const [ka, kb] = queue.pop()!;
      placed.set(a, ka);
      placed.set(b, kb);
      solution.push([a, b]);
      remaining.delete(a);
      remaining.delete(b);
    }
    if (!stuck) return { placed, solution };
  }
  return null;
}

/** A new board plus the removal order that clears it (proof that it is solvable). */
export function generateBoard(seed: number, config: MahjongConfig): { state: MahjongState; solution: [number, number][] } {
  const def = LAYOUTS[config.layout];
  const rng = seededRng(seed);
  const pairs = shuffle(allPairs(), rng).slice(0, def.slots.length / 2);
  const positions = def.slots.map((_, i) => i);
  const result = placeSolvable(def.slots, positions, pairs, rng);
  if (!result) throw new Error("Could not generate a board");
  const { placed, solution } = result;
  const state: MahjongState = {
    layout: config.layout,
    slots: def.slots,
    tiles: positions.map((i) => placed.get(i)!),
    score: 0,
    matches: 0,
    hints: 0,
    shuffles: 0,
    undos: 0,
    lastMatchAt: null,
    combo: 0,
    won: false,
  };
  return { state, solution };
}

export const newBoard = (seed: number, config: MahjongConfig): MahjongState => generateBoard(seed, config).state;

/** Re-deals the remaining tiles onto the remaining positions, keeping the board solvable. */
export function reshuffle(s: MahjongState, seed: number): boolean {
  const positions = s.tiles.flatMap((t, i) => (t === null ? [] : [i]));
  if (positions.length < 2) return false;
  const byKey = new Map<number, number[]>();
  for (const i of positions) {
    const k = s.tiles[i]!;
    byKey.set(matchKey(k), [...(byKey.get(matchKey(k)) ?? []), k]);
  }
  const pairs: [number, number][] = [];
  for (const kinds of byKey.values()) for (let i = 0; i + 1 < kinds.length; i += 2) pairs.push([kinds[i]!, kinds[i + 1]!]);
  const result = placeSolvable(s.slots, positions, pairs, seededRng((seed ^ Math.imul(s.shuffles + 1, 0x9e3779b1)) >>> 0));
  if (!result) return false;
  for (const i of positions) s.tiles[i] = result.placed.get(i)!;
  return true;
}

/**
 * True when no re-deal can save the board: the remaining positions themselves
 * can't be cleared in pairs (e.g. tiles stacked in a single column). Only undo helps.
 */
export function isDeadEnd(s: MahjongState): boolean {
  if (s.won || availablePairs(s).length) return false;
  const probe: MahjongState = { ...s, tiles: [...s.tiles] };
  return !reshuffle(probe, 1);
}

/**
 * The pair to suggest as a hint: one after which the board can still be
 * cleared with the current tiles, found by a bounded depth-first search over
 * which tiles remain (the layout and tiles are fixed, so that set is the whole
 * state). If the search runs out of budget it falls back to a pair that at
 * least avoids an immediate dead end, then to any available pair.
 */
export function safeHint(s: MahjongState, budget = 2500): [number, number] | null {
  const pairs = availablePairs(s);
  if (!pairs.length) return null;
  const tiles = [...s.tiles];
  const probe: MahjongState = { ...s, tiles };
  const failed = new Set<string>();
  let nodes = 0;
  const clearable = (): boolean | null => {
    if (tiles.every((t) => t === null)) return true;
    if (++nodes > budget) return null;
    const key = tiles.map((t) => (t === null ? "0" : "1")).join("");
    if (failed.has(key)) return false;
    for (const [a, b] of availablePairs(probe)) {
      const ka = tiles[a]!;
      const kb = tiles[b]!;
      tiles[a] = tiles[b] = null;
      const r = clearable();
      tiles[a] = ka;
      tiles[b] = kb;
      if (r !== false) return r;
    }
    failed.add(key);
    return false;
  };
  let fallback: [number, number] | null = null;
  for (const [a, b] of pairs) {
    const ka = tiles[a]!;
    const kb = tiles[b]!;
    tiles[a] = tiles[b] = null;
    const r = clearable();
    const notStuck = !fallback && (tiles.every((t) => t === null) || availablePairs(probe).length > 0);
    tiles[a] = ka;
    tiles[b] = kb;
    if (r === true) return [a, b];
    if (notStuck) fallback = [a, b];
  }
  return fallback ?? pairs[0]!;
}

// ---------------------------------------------------------------------------
// Play
// ---------------------------------------------------------------------------

const snapshot = (s: MahjongState): MahjongState => ({ ...s, tiles: [...s.tiles] });

export class MahjongGame {
  state: MahjongState;
  private history: MahjongState[] = [];
  constructor(
    private readonly seed: number,
    config: MahjongConfig,
  ) {
    this.state = newBoard(seed, config);
  }

  get canUndo() {
    return this.history.length > 0 && !this.state.won;
  }

  apply(move: MahjongMove): boolean {
    const s = this.state;
    if (s.won) return false;
    switch (move.k) {
      case "match": {
        const { a, b } = move;
        if (a === b || s.tiles[a] == null || s.tiles[b] == null) return false;
        if (!tilesMatch(s.tiles[a]!, s.tiles[b]!)) return false;
        const present = (j: number) => s.tiles[j] !== null;
        if (!isFree(s.slots, present, a) || !isFree(s.slots, present, b)) return false;
        this.history.push(snapshot(s));
        s.tiles[a] = null;
        s.tiles[b] = null;
        s.matches++;
        s.combo = s.lastMatchAt !== null && move.t - s.lastMatchAt <= COMBO_WINDOW_MS ? s.combo + 1 : 0;
        s.lastMatchAt = move.t;
        s.score += SCORE.match + Math.min(s.combo, 5) * SCORE.comboBonus;
        if (s.tiles.every((t) => t === null)) s.won = true;
        return true;
      }
      case "undo": {
        const prev = this.history.pop();
        if (!prev) return false;
        this.state = { ...prev, undos: s.undos + 1, hints: s.hints, shuffles: s.shuffles };
        return true;
      }
      case "shuffle": {
        this.history.push(snapshot(s));
        if (!reshuffle(s, this.seed)) {
          this.history.pop();
          return false;
        }
        s.shuffles++;
        return true;
      }
      case "hint":
        s.hints++;
        return true;
    }
  }
}

export const totalScore = (s: MahjongState, durationMs: number) => {
  const par = LAYOUTS[s.layout].parSeconds;
  const timeBonus = s.won ? Math.max(0, par - Math.floor(durationMs / 1000)) * 3 : 0;
  const penalties = s.hints * SCORE.hint + s.shuffles * SCORE.shuffle + s.undos * SCORE.undo;
  return Math.max(0, s.score + penalties + (s.won ? SCORE.clear + timeBonus : 0));
};

export const mahjongGarden: SoloGameDefinition<MahjongConfig, MahjongMove[]> = {
  id: "mahjong-garden",
  configSchema: mahjongConfigSchema,
  logSchema: mahjongLogSchema,
  verify(seed, config, log): SoloVerifyResult {
    const timing = checkTimeline(
      log.map((m) => m.t),
      4 * 60 * 60 * 1000,
    );
    if (timing) return { ok: false, reason: timing };
    const game = new MahjongGame(seed, config);
    for (const move of log) if (!game.apply(move)) return { ok: false, reason: "The move log contains an illegal move" };
    const s = game.state;
    const durationMs = log.length ? log[log.length - 1]!.t : 0;
    return {
      ok: true,
      result: {
        score: totalScore(s, durationMs),
        completed: s.won,
        durationMs,
        details: { layout: s.layout, matches: s.matches, hints: s.hints, shuffles: s.shuffles },
      },
    };
  },
};
